{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "What is the objective of this production plan — are we maximizing total profit (unit price minus raw material cost minus processing cost, summed over all products), or is there another objective such as maximizing total revenue or minimizing total cost?"
  ],
  "rationale": "The response asks for a single policy choice regarding the optimization objective, presenting alternatives within one coherent question."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Are there any demand limits (maximum number of units that can be sold) for each of the three products, or can we produce and sell unlimited quantities of each product as long as the equipment capacity constraints are satisfied?"
  ],
  "rationale": "The response asks a single clarification question regarding whether demand limits exist or if quantities are unlimited, which constitutes one independent semantic request."
}

